SOURCE_TRANSFORMS = {
 'eagle-open': (1920 / 1652, 1080 / 930, -134 * 1600 / 1652, -150 * 900 / 930),
}

manifest = {}
for name,(source,points) in CUTOUTS.items():
 image=Image.open(SOURCE/(source+'.webp')).convert('RGBA')
 mask=Image.new('L',image.size); ImageDraw.Draw(mask).polygon(points,fill=255)
 box=mask.getbbox(); image.putalpha(mask); image=image.crop(box)
 factor=min(1,580/max(image.size)); size=(round(image.width*factor),round(image.height*factor))
 image=image.resize(size,Image.Resampling.LANCZOS)
 alpha=image.getchannel('A').point(lambda x:255 if x>100 else 0)
 image=image.convert('RGB').quantize(colors=56,method=Image.Quantize.MEDIANCUT).convert('RGBA'); image.putalpha(alpha)
 tmp=Path('/tmp')/('gta-object-'+name+'.png'); image.save(tmp)
 dest=OUT/(name+'.svg')
 vtracer.convert_image_to_svg_py(str(tmp),str(dest),colormode='color',hierarchical='stacked',mode='spline',filter_speckle=4,color_precision=6,layer_difference=24,corner_threshold=60,length_threshold=4,max_iterations=10,splice_threshold=45,path_precision=1)
 svg=dest.read_text(); svg=re.sub(r'<\?xml[^>]*>','',svg).replace('<!-- Generator: visioncortex VTracer 0.6.12 -->','')
 # Give scaled image instances a real coordinate system and a transparent guard
 # around traced curves. overflow:visible on an <img> cannot repair its SVG crop.
 svg=svg.replace('<svg ',f'<svg viewBox="-2 -2 {size[0]+4} {size[1]+4}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="{name.replace("-"," ")}" ',1)
 dest.write_text(svg.strip())
 x0,y0,x1,y1=box
 sx,sy,ox,oy=SOURCE_TRANSFORMS.get(source,(1,1,0,0))
 manifest[name]={'x':round((x0+x1)/2*sx+ox,4),'y':round((y0+y1)/2*sy+oy,4),'w':round((x1-x0)*sx,4),'h':round((y1-y0)*sy,4),'source':source}
 print(name,round(dest.stat().st_size/1024),'KB',flush=True)
(OUT/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
